const HISTORIA_EDITORIAL_LOTE_2={"HIS-011":{"steps":["El 18 de septiembre de 1810 se formó la Primera Junta Nacional de Gobierno en Santiago.","Fue un hito del proceso de independencia, no la declaración formal de independencia.","La independencia se proclamó en 1818; confundir ambas fechas lleva a elegir un distractor."],"easy":"El 18 de septiembre recuerda la Primera Junta de 1810, no la proclamación de independencia.","example":"En una línea de tiempo: Junta de Gobierno en 1810; declaración de independencia en 1818."},"HIS-012":{"steps":["La expansión salitrera se desarrolló en el norte de Chile a fines del siglo XIX.","Las oficinas salitreras requirieron trabajadores, transporte y abastecimiento.","Esto favoreció migraciones, asentamientos y ciudades vinculadas a la explotación y exportación."],"easy":"El salitre atrajo trabajadores al norte y generó localidades y comercio alrededor de las oficinas.","example":"Una oficina salitrera necesitaba operarios, almacenes y ferrocarril: su actividad podía hacer crecer asentamientos cercanos."},"HIS-013":{"steps":["La Ilustración fue un movimiento intelectual que valoró la razón y el examen crítico.","Sus pensadores discutieron el absolutismo y defendieron distintas ideas sobre libertad y gobierno.","Por eso la opción sobre razón y crítica a la autoridad absoluta representa mejor este movimiento."],"easy":"Los ilustrados sostenían que las ideas políticas debían poder discutirse racionalmente, no aceptarse solo por tradición.","example":"Montesquieu argumentó a favor de distribuir el poder político para limitar su concentración."},"HIS-014":{"steps":["La Segunda Guerra Mundial terminó en 1945.","Ese mismo año se fundó la Organización de las Naciones Unidas mediante la Carta de San Francisco.","Su propósito central incluyó promover la paz y la cooperación internacional."],"easy":"La ONU nació en 1945, al terminar la Segunda Guerra Mundial, para facilitar cooperación y prevenir nuevos conflictos.","example":"La Carta de las Naciones Unidas se firmó en junio de 1945 y entró en vigor en octubre de ese año."},"HIS-015":{"steps":["Pluralismo significa reconocer la existencia legítima de diversas ideas e intereses.","En política permite que grupos distintos se organicen y expresen proyectos en un marco democrático.","No implica que todos piensen igual ni que solo un grupo pueda participar."],"easy":"Una democracia pluralista acepta partidos y organizaciones con posiciones diferentes.","example":"Dos agrupaciones pueden discrepar sobre educación y presentar propuestas distintas sin perder su derecho a participar."},"HIS-016":{"steps":["La pregunta pide identificar la institución que ejerce jurisdicción en Chile.","Los tribunales que integran el Poder Judicial resuelven causas dentro de sus competencias.","La elaboración de leyes corresponde principalmente al Poder Legislativo; no es la función consultada."],"easy":"Los jueces y tribunales resuelven controversias y aplican el derecho en casos concretos.","example":"Ante un conflicto civil que llega a juicio, un tribunal competente puede dictar una sentencia."},"HIS-017":{"steps":["La Ley de Transparencia reconoce el derecho de solicitar información pública a organismos sujetos a ella.","El mecanismo es presentar una solicitud de acceso a la información pública.","Existen causales legales de reserva, por lo que no toda información puede entregarse sin límites."],"easy":"Puedes pedir información pública a organismos del Estado mediante una solicitud formal.","example":"Una persona puede solicitar antecedentes de gastos de un organismo público, sujeto a las excepciones legales."},"HIS-018":{"steps":["El ingreso nominal es la cantidad de dinero recibida, sin ajustar por inflación.","Si los precios suben y el ingreso nominal se mantiene, con ese dinero se compran menos bienes.","Por tanto, disminuye el poder adquisitivo o ingreso real."],"easy":"Si tu sueldo no cambia pero las cosas cuestan más, tu dinero alcanza para menos.","example":"Con $10.000 compras diez productos de $1.000; si cada uno sube a $1.250, solo puedes comprar ocho."},"HIS-019":{"steps":["Un bien público puro es no rival: el consumo de una persona no reduce el disponible para otra.","También es no excluible: resulta inviable o muy difícil impedir que alguien se beneficie.","La defensa nacional suele usarse como ejemplo; no debe confundirse con cualquier servicio financiado por el Estado."],"easy":"Un bien público puro beneficia simultáneamente a muchas personas y no se puede restringir fácilmente su uso.","example":"El alumbrado de una calle se aproxima al concepto: la iluminación de una persona no impide que otras aprovechen esa misma luz."},"HIS-020":{"steps":["En Chile, las mujeres ya habían accedido al sufragio municipal en 1934.","La ley de 1949 amplió el derecho a votar en elecciones parlamentarias y presidenciales.","Las mujeres participaron por primera vez en una elección presidencial chilena en 1952."],"easy":"La ampliación legal fue en 1949; la primera elección presidencial en que votaron mujeres fue en 1952.","example":"Para distinguir las fechas: 1934 corresponde al voto municipal, 1949 a la ley de ampliación y 1952 a su ejercicio presidencial."}};
