const HISTORIA_EXPLICACIONES_BASE={"HIS-037":{"steps":["La pregunta plantea: ¿Cuál es un ejemplo de discriminación arbitraria?","La discriminación arbitraria establece distinciones sin justificación razonable que afectan el ejercicio de derechos.","La alternativa «Negar un servicio por un prejuicio sin justificación razonable» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"La discriminación arbitraria establece distinciones sin justificación razonable que afectan el ejercicio de derechos.","example":"Caso aplicado: La discriminación arbitraria establece distinciones sin justificación razonable que afectan el ejercicio de derechos."},"HIS-038":{"steps":["La pregunta plantea: ¿Qué aporta la libertad de prensa a una democracia?","Una prensa libre contribuye al debate y control público, aunque requiere verificación y responsabilidad.","La alternativa «Facilita información y fiscalización del poder» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Una prensa libre contribuye al debate y control público, aunque requiere verificación y responsabilidad.","example":"Caso aplicado: Una prensa libre contribuye al debate y control público, aunque requiere verificación y responsabilidad."},"HIS-039":{"steps":["La pregunta plantea: ¿Qué implica el debido proceso?","El debido proceso protege garantías como defensa, imparcialidad y procedimientos establecidos por la ley.","La alternativa «Garantías para ser oído y juzgado conforme a procedimientos legales» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El debido proceso protege garantías como defensa, imparcialidad y procedimientos establecidos por la ley.","example":"Caso aplicado: El debido proceso protege garantías como defensa, imparcialidad y procedimientos establecidos por la ley."},"HIS-040":{"steps":["La pregunta plantea: ¿Qué representa el producto interno bruto de un país?","El PIB mide el valor de la producción final realizada dentro de una economía durante un período.","La alternativa «El valor de bienes y servicios finales producidos en un período» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El PIB mide el valor de la producción final realizada dentro de una economía durante un período.","example":"Caso aplicado: El PIB mide el valor de la producción final realizada dentro de una economía durante un período."},"HIS-041":{"steps":["La pregunta plantea: ¿Qué caracteriza al desempleo en estadísticas laborales?","El desempleo considera criterios de falta de ocupación, búsqueda y disponibilidad según las mediciones laborales.","La alternativa «Personas sin trabajo que buscan empleo y están disponibles» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El desempleo considera criterios de falta de ocupación, búsqueda y disponibilidad según las mediciones laborales.","example":"Caso aplicado: El desempleo considera criterios de falta de ocupación, búsqueda y disponibilidad según las mediciones laborales."},"HIS-042":{"steps":["La pregunta plantea: ¿Qué ocurre si aumenta la oferta de un producto y la demanda se mantiene constante, en un mercado competitivo?","Un desplazamiento de la oferta hacia la derecha suele reducir el precio de equilibrio y elevar la cantidad transada.","La alternativa «El precio de equilibrio tiende a disminuir» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Un desplazamiento de la oferta hacia la derecha suele reducir el precio de equilibrio y elevar la cantidad transada.","example":"Caso aplicado: Un desplazamiento de la oferta hacia la derecha suele reducir el precio de equilibrio y elevar la cantidad transada."},"HIS-043":{"steps":["La pregunta plantea: ¿Qué es un impuesto progresivo?","Un impuesto progresivo aumenta la carga relativa a medida que crece la capacidad contributiva medida por su base.","La alternativa «Uno cuya tasa efectiva aumenta al crecer la base gravada» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Un impuesto progresivo aumenta la carga relativa a medida que crece la capacidad contributiva medida por su base.","example":"Caso aplicado: Un impuesto progresivo aumenta la carga relativa a medida que crece la capacidad contributiva medida por su base."},"HIS-044":{"steps":["La pregunta plantea: ¿Cuál es una consecuencia posible de una externalidad negativa?","Una externalidad negativa impone costos a terceros, como contaminación que afecta a vecinos.","La alternativa «Costos para terceros no incorporados plenamente en el precio» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Una externalidad negativa impone costos a terceros, como contaminación que afecta a vecinos.","example":"Caso aplicado: Una externalidad negativa impone costos a terceros, como contaminación que afecta a vecinos."},"HIS-045":{"steps":["La pregunta plantea: ¿Qué significa diversificar una inversión?","La diversificación puede reducir riesgos específicos, aunque no elimina todos los riesgos de mercado.","La alternativa «Distribuir recursos entre distintos activos para reducir exposición específica» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"La diversificación puede reducir riesgos específicos, aunque no elimina todos los riesgos de mercado.","example":"Caso aplicado: La diversificación puede reducir riesgos específicos, aunque no elimina todos los riesgos de mercado."},"HIS-046":{"steps":["La pregunta plantea: Una carta de 1900 describe jornadas laborales extensas. ¿Qué se puede inferir con mayor prudencia?","La fuente testimonia una experiencia situada; generalizar requiere contrastar otros documentos y datos.","La alternativa «Que el autor percibía condiciones laborales exigentes en su entorno» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"La fuente testimonia una experiencia situada; generalizar requiere contrastar otros documentos y datos.","example":"Caso aplicado: La fuente testimonia una experiencia situada; generalizar requiere contrastar otros documentos y datos."},"HIS-047":{"steps":["La pregunta plantea: Un gráfico muestra aumento sostenido de matrícula escolar entre 1950 y 1970. ¿Qué conclusión respalda?","El gráfico respalda una tendencia cuantitativa de matrícula, pero no demuestra por sí mismo calidad ni cobertura homogénea.","La alternativa «La matrícula creció en el período mostrado» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El gráfico respalda una tendencia cuantitativa de matrícula, pero no demuestra por sí mismo calidad ni cobertura homogénea.","example":"Caso aplicado: El gráfico respalda una tendencia cuantitativa de matrícula, pero no demuestra por sí mismo calidad ni cobertura homogénea."},"HIS-048":{"steps":["La pregunta plantea: Dos periódicos describen de modo distinto una misma protesta. ¿Qué estrategia de análisis es más apropiada?","Contrastar fuentes permite reconocer enfoques y sesgos sin renunciar a la verificación factual.","La alternativa «Comparar perspectivas, evidencias y contexto editorial» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Contrastar fuentes permite reconocer enfoques y sesgos sin renunciar a la verificación factual.","example":"Caso aplicado: Contrastar fuentes permite reconocer enfoques y sesgos sin renunciar a la verificación factual."},"HIS-049":{"steps":["La pregunta plantea: Un mapa histórico muestra cambios fronterizos. ¿Qué otra evidencia ayudaría a explicar sus causas?","Para explicar transformaciones territoriales se deben contrastar mapas con documentos políticos y procesos históricos.","La alternativa «Tratados, conflictos y decisiones políticas de la época» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Para explicar transformaciones territoriales se deben contrastar mapas con documentos políticos y procesos históricos.","example":"Caso aplicado: Para explicar transformaciones territoriales se deben contrastar mapas con documentos políticos y procesos históricos."},"HIS-050":{"steps":["La pregunta plantea: Un censo registra un aumento de población urbana de 40% a 60% en veinte años. ¿Qué indica ese dato?","Los porcentajes describen la participación relativa de la población urbana, no la variación absoluta del total.","La alternativa «Que creció la proporción de habitantes urbanos» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Los porcentajes describen la participación relativa de la población urbana, no la variación absoluta del total.","example":"Caso aplicado: Los porcentajes describen la participación relativa de la población urbana, no la variación absoluta del total."},"HIS-051":{"steps":["La pregunta plantea: ¿Qué efecto tuvo la llegada del ferrocarril a diversas regiones chilenas en el siglo XIX?","El ferrocarril mejoró la conexión entre centros productivos, ciudades y puertos.","La alternativa «Facilitó el transporte y la articulación de mercados» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El ferrocarril mejoró la conexión entre centros productivos, ciudades y puertos.","example":"Caso aplicado: El ferrocarril mejoró la conexión entre centros productivos, ciudades y puertos."},"HIS-052":{"steps":["La pregunta plantea: ¿Qué hecho suele marcar el inicio de la Primera Guerra Mundial en 1914?","El atentado de Sarajevo desencadenó una crisis diplomática y militar entre potencias europeas.","La alternativa «El asesinato del archiduque Francisco Fernando» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El atentado de Sarajevo desencadenó una crisis diplomática y militar entre potencias europeas.","example":"Caso aplicado: El atentado de Sarajevo desencadenó una crisis diplomática y militar entre potencias europeas."},"HIS-053":{"steps":["La pregunta plantea: ¿Qué finalidad tiene la rendición de cuentas de una autoridad pública?","La rendición de cuentas permite conocer decisiones, uso de recursos y responsabilidades públicas.","La alternativa «Permitir evaluar y controlar el ejercicio de sus funciones» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"La rendición de cuentas permite conocer decisiones, uso de recursos y responsabilidades públicas.","example":"Caso aplicado: La rendición de cuentas permite conocer decisiones, uso de recursos y responsabilidades públicas."},"HIS-054":{"steps":["La pregunta plantea: Si una persona ahorra $10.000 mensuales durante seis meses sin intereses, ¿cuánto acumula?","El ahorro acumulado es 10.000 multiplicado por seis meses: 60.000 pesos.","La alternativa «$60.000» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El ahorro acumulado es 10.000 multiplicado por seis meses: 60.000 pesos.","example":"Caso aplicado: El ahorro acumulado es 10.000 multiplicado por seis meses: 60.000 pesos."},"HIS-055":{"steps":["La pregunta plantea: Un registro electoral muestra que votó el 70% del padrón. ¿Qué conclusión se justifica?","La participación se calcula sobre personas inscritas o habilitadas, no necesariamente sobre toda la población.","La alternativa «Participaron siete de cada diez personas habilitadas» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"La participación se calcula sobre personas inscritas o habilitadas, no necesariamente sobre toda la población.","example":"Caso aplicado: La participación se calcula sobre personas inscritas o habilitadas, no necesariamente sobre toda la población."},"HIS-056":{"steps":["La pregunta plantea: ¿Qué fue la ocupación de la Araucanía en el siglo XIX?","El avance militar y administrativo del Estado chileno transformó el territorio y las condiciones de vida mapuche.","La alternativa «Un proceso de incorporación territorial estatal que afectó profundamente al pueblo mapuche» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El avance militar y administrativo del Estado chileno transformó el territorio y las condiciones de vida mapuche.","example":"Caso aplicado: El avance militar y administrativo del Estado chileno transformó el territorio y las condiciones de vida mapuche."},"HIS-057":{"steps":["La pregunta plantea: ¿Qué buscaba el Plan Marshall después de la Segunda Guerra Mundial?","El programa estadounidense entregó apoyo para la recuperación económica europea de posguerra.","La alternativa «Apoyar la reconstrucción económica de Europa occidental» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El programa estadounidense entregó apoyo para la recuperación económica europea de posguerra.","example":"Caso aplicado: El programa estadounidense entregó apoyo para la recuperación económica europea de posguerra."},"HIS-058":{"steps":["La pregunta plantea: ¿Qué significa soberanía popular en una democracia?","La soberanía popular sitúa en la ciudadanía el fundamento de la autoridad política.","La alternativa «Que la legitimidad del poder político se funda en el pueblo» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"La soberanía popular sitúa en la ciudadanía el fundamento de la autoridad política.","example":"Caso aplicado: La soberanía popular sitúa en la ciudadanía el fundamento de la autoridad política."},"HIS-059":{"steps":["La pregunta plantea: Una municipalidad dispone de presupuesto para construir una biblioteca o mejorar una plaza, pero no ambas. Decide construir la biblioteca. ¿Qué representa su costo de oportunidad?","El costo de oportunidad de elegir la biblioteca es el beneficio de la mejor alternativa descartada: mejorar la plaza. No equivale al costo monetario de todas las opciones.","La alternativa «El beneficio de mejorar la plaza al que se renunció» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"El costo de oportunidad de elegir la biblioteca es el beneficio de la mejor alternativa descartada: mejorar la plaza. No equivale al costo monetario de todas las opciones.","example":"Caso aplicado: El costo de oportunidad de elegir la biblioteca es el beneficio de la mejor alternativa descartada: mejorar la plaza. No equivale al costo monetario de todas las opciones."},"HIS-060":{"steps":["La pregunta plantea: Una fotografía muestra una protesta, pero no incluye fecha ni lugar. ¿Qué conviene hacer antes de interpretarla?","La contextualización evita interpretaciones erróneas y ayuda a verificar qué representa realmente la imagen.","La alternativa «Investigar procedencia, contexto y autenticidad» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"La contextualización evita interpretaciones erróneas y ayuda a verificar qué representa realmente la imagen.","example":"Caso aplicado: La contextualización evita interpretaciones erróneas y ayuda a verificar qué representa realmente la imagen."},"HIS-061":{"steps":["La pregunta plantea: ¿Qué significó la nacionalización del cobre en Chile en 1971?","La reforma constitucional de 1971 permitió nacionalizar empresas de la gran minería del cobre.","La alternativa «La transferencia al Estado de la gran minería del cobre mediante reforma constitucional» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"La reforma constitucional de 1971 permitió nacionalizar empresas de la gran minería del cobre.","example":"Caso aplicado: La reforma constitucional de 1971 permitió nacionalizar empresas de la gran minería del cobre."},"HIS-062":{"steps":["La pregunta plantea: ¿Qué fue la Gran Depresión iniciada en 1929?","La crisis iniciada en 1929 produjo contracción económica, desempleo y efectos internacionales.","La alternativa «Una crisis económica internacional de gran magnitud» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"La crisis iniciada en 1929 produjo contracción económica, desempleo y efectos internacionales.","example":"Caso aplicado: La crisis iniciada en 1929 produjo contracción económica, desempleo y efectos internacionales."},"HIS-063":{"steps":["La pregunta plantea: ¿Qué función cumplen las elecciones periódicas en una democracia representativa?","Las elecciones periódicas permiten a la ciudadanía elegir representantes y evaluar su gestión.","La alternativa «Permiten renovar autoridades y exigir responsabilidad política» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Las elecciones periódicas permiten a la ciudadanía elegir representantes y evaluar su gestión.","example":"Caso aplicado: Las elecciones periódicas permiten a la ciudadanía elegir representantes y evaluar su gestión."},"HIS-064":{"steps":["La pregunta plantea: ¿Qué suele ocurrir con la demanda de un bien normal cuando aumenta el ingreso, manteniendo lo demás constante?","Por definición, la cantidad demandada de un bien normal tiende a aumentar cuando sube el ingreso.","La alternativa «Tiende a aumentar» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Por definición, la cantidad demandada de un bien normal tiende a aumentar cuando sube el ingreso.","example":"Caso aplicado: Por definición, la cantidad demandada de un bien normal tiende a aumentar cuando sube el ingreso."},"HIS-065":{"steps":["La pregunta plantea: Un gráfico presenta solo valores absolutos de desempleados. ¿Qué dato adicional permite comparar tasas entre países?","Para comparar tasas de desempleo se necesita el número de personas desempleadas relativo a la fuerza laboral.","La alternativa «El tamaño de sus fuerzas laborales» responde al criterio indicado; no confundas este concepto con una afirmación más amplia que la evidencia no permite."],"easy":"Para comparar tasas de desempleo se necesita el número de personas desempleadas relativo a la fuerza laboral.","example":"Caso aplicado: Para comparar tasas de desempleo se necesita el número de personas desempleadas relativo a la fuerza laboral."}};
for(const q of window.CACHASTE_HISTORIA){if(HISTORIA_EXPLICACIONES_BASE[q.id]){q.editorial=HISTORIA_EXPLICACIONES_BASE[q.id];q.reviewStatus='explicacion_ampliada_pendiente_verificacion_externa';}}

const HISTORIA_EDITORIAL_LOTE_3={"HIS-037":{"steps":["Discriminación arbitraria es una distinción sin justificación razonable que afecta derechos.","Negar un servicio por prejuicio cumple ese criterio: la exclusión no responde a una razón legítima.","No toda diferencia de trato es arbitraria; debe examinarse su justificación."],"easy":"Es excluir injustamente a alguien por un prejuicio, sin una razón válida.","example":"Si un local niega atención solo por el origen de una persona, existe una distinción injustificada que puede constituir discriminación arbitraria."},"HIS-038":{"steps":["La libertad de prensa permite informar sobre asuntos públicos.","También facilita investigar y cuestionar decisiones de autoridades.","No garantiza que toda publicación sea correcta; exige contrastar información."],"easy":"La prensa libre ayuda a que la ciudadanía se informe y fiscalice a quienes gobiernan.","example":"Una investigación periodística documentada sobre gastos públicos permite que las personas exijan explicaciones."},"HIS-039":{"steps":["El debido proceso exige reglas y garantías al decidir sobre derechos y responsabilidades.","Incluye la posibilidad de defensa, ser oído y acudir a un órgano imparcial.","No equivale a que una persona siempre obtenga un fallo favorable."],"easy":"Un juicio justo requiere que puedas defenderte y que se respeten procedimientos legales.","example":"Si alguien es acusado, debe conocer los cargos y contar con oportunidades reales de presentar su defensa."},"HIS-040":{"steps":["El PIB mide producción final dentro de un territorio durante un período.","Se consideran bienes y servicios finales para evitar contar repetidamente insumos intermedios.","No equivale a riqueza acumulada ni mide directamente bienestar o desigualdad."],"easy":"Es el valor de lo producido en bienes y servicios finales dentro de un país durante un tiempo.","example":"Si una panadería compra harina y vende pan, el PIB evita sumar dos veces el valor de la harina incorporada al pan."},"HIS-041":{"steps":["La condición de desocupación estadística combina ausencia de empleo, búsqueda y disponibilidad según el período de referencia.","Una persona sin trabajo que no busca empleo no se clasifica automáticamente como desempleada.","La tasa de desocupación se calcula respecto de la fuerza de trabajo, no de toda la población."],"easy":"Para contar como desempleado no basta con no trabajar: importan la búsqueda y la disponibilidad.","example":"Quien busca empleo activamente y puede empezar a trabajar puede integrar la población desocupada; quien no busca suele quedar fuera de la fuerza laboral."},"HIS-042":{"steps":["Al aumentar la oferta, los vendedores están dispuestos a ofrecer más a cada precio.","Si la demanda se mantiene, el nuevo equilibrio competitivo suele tener precio menor.","La cantidad de equilibrio tiende a aumentar; no confundas este movimiento con una caída de demanda."],"easy":"Más oferta, con la misma demanda, tiende a bajar el precio de equilibrio.","example":"Si aumenta la producción de tomates sin cambiar las preferencias de compra, el precio competitivo puede bajar mientras se venden más tomates."},"HIS-043":{"steps":["Un impuesto progresivo hace crecer la carga relativa a medida que aumenta la base imponible.","La progresividad se observa en la tasa media o efectiva, no solo en el monto pagado.","Un impuesto proporcional mantiene constante la tasa; uno regresivo reduce la carga relativa al aumentar la base."],"easy":"Quien tiene una base imponible mayor paga una proporción mayor, no solo más pesos.","example":"Si la tasa efectiva pasa de 5% a 15% entre tramos de ingreso, el esquema es progresivo."},"HIS-044":{"steps":["Una externalidad negativa aparece cuando una actividad genera costos para terceros.","Esos costos no quedan incorporados plenamente en las decisiones o precios del mercado.","Por ello la cantidad producida sin correcciones puede superar la socialmente eficiente."],"easy":"Es un daño que afecta a otros sin que quien lo causa asuma todo su costo.","example":"Una fábrica que contamina el aire impone gastos de salud a vecinos, aunque esos gastos no aparezcan en el precio del producto."},"HIS-045":{"steps":["Diversificar significa distribuir la inversión entre activos con riesgos distintos.","Puede reducir la exposición a la pérdida de un solo activo o sector.","No elimina riesgos generales que afectan a todo el mercado."],"easy":"No poner todo el dinero en un solo activo reduce el riesgo de depender de él.","example":"Invertir en varios sectores puede amortiguar la caída de uno, aunque una crisis general todavía afecte a todos."},"HIS-046":{"steps":["Una carta escrita en 1900 es fuente primaria sobre la perspectiva de su autor.","Describe jornadas extensas en un contexto particular.","No demuestra por sí sola que todas las personas trabajaran en idénticas condiciones."],"easy":"La carta permite saber cómo el autor describía su trabajo, no cómo era todo el país.","example":"Para generalizar habría que contrastar esa carta con registros laborales, otras cartas y documentos de la época."},"HIS-047":{"steps":["El gráfico muestra un aumento sostenido de matrícula entre 1950 y 1970.","Ese dato respalda el crecimiento de la cantidad de estudiantes registrados.","No permite concluir automáticamente que mejoró la calidad de la enseñanza."],"easy":"Sabemos que aumentó la matrícula, pero no que las clases fueran mejores.","example":"Una escuela puede matricular más alumnos sin que el gráfico indique sus resultados de aprendizaje."},"HIS-048":{"steps":["Dos periódicos pueden seleccionar hechos y enfoques diferentes sobre una protesta.","Conviene comparar datos verificables, fuentes citadas y contexto editorial.","Las diferencias no obligan a creer que ambos relatos son igualmente precisos."],"easy":"Compara qué pruebas aporta cada diario y desde qué perspectiva informa.","example":"Si uno habla de asistentes y otro de incidentes, revisa fotografías, cifras verificables y qué aspectos omitió cada uno."},"HIS-049":{"steps":["Un mapa muestra cómo cambiaron fronteras, pero no explica necesariamente por qué.","Tratados, conflictos y decisiones políticas pueden documentar las causas.","El análisis histórico requiere vincular representación espacial y fuentes de la época."],"easy":"Para explicar una frontera no basta mirar el mapa: hay que investigar los acuerdos y conflictos.","example":"Dos mapas de fechas distintas muestran un cambio; un tratado firmado entre esas fechas puede ayudar a explicar su origen."},"HIS-050":{"steps":["El porcentaje de población urbana pasa de 40% a 60%.","Esto demuestra un aumento de 20 puntos porcentuales en su participación relativa.","No demuestra por sí solo cuántas personas adicionales viven en ciudades sin conocer el total poblacional."],"easy":"Subió la proporción urbana, pero no sabemos el aumento exacto de habitantes.","example":"Si el país tenía 100 personas al inicio y 200 al final, pasar de 40% a 60% equivale a 40 y 120 personas urbanas respectivamente."},"HIS-051":{"steps":["El ferrocarril redujo tiempos y costos de transporte en diversos recorridos del siglo XIX.","Conectó zonas productivas, ciudades y puertos, facilitando circulación de bienes y personas.","Su efecto varió según región y trazado; no transformó todos los territorios de igual forma."],"easy":"Los trenes ayudaron a conectar mercados y transportar producción.","example":"Una zona agrícola con acceso ferroviario podía enviar productos con mayor facilidad a un puerto o ciudad."}};
for(const q of window.CACHASTE_HISTORIA){if(HISTORIA_EDITORIAL_LOTE_3[q.id]){q.editorial=HISTORIA_EDITORIAL_LOTE_3[q.id];q.reviewStatus='revisado_conceptualmente';}}

const HISTORIA_EDITORIAL_LOTE_4={"HIS-052":{"steps":["El 28 de junio de 1914 fue asesinado el archiduque Francisco Fernando en Sarajevo.","El atentado desencadenó una crisis diplomática que escaló hacia la guerra entre potencias.","Fue el detonante inmediato; no debe confundirse con causas estructurales como alianzas y rivalidades."],"easy":"El asesinato en Sarajevo fue la chispa de una guerra con tensiones anteriores.","example":"El atentado desencadenó la crisis de julio; las alianzas y rivalidades explican por qué se amplió el conflicto."},"HIS-053":{"steps":["Rendir cuentas implica informar y justificar decisiones de una autoridad.","Permite fiscalizar el uso de recursos y evaluar resultados y responsabilidades.","No consiste solo en publicar cifras sin posibilidad de escrutinio."],"easy":"La autoridad debe explicar qué hizo, por qué y con qué recursos.","example":"Un municipio publica gastos de una obra y responde preguntas sobre su ejecución: eso facilita control ciudadano."},"HIS-054":{"steps":["El ahorro mensual es de $10.000.","Se realizan seis depósitos iguales sin intereses.","Multiplica 10.000 × 6 = 60.000 pesos."],"easy":"Seis meses ahorrando diez mil pesos suman sesenta mil.","example":"Mes 1: $10.000; mes 2: $20.000 acumulados; al mes 6: $60.000, sin intereses."},"HIS-055":{"steps":["El padrón reúne personas habilitadas para votar.","El 70% equivale a 70 de cada 100 integrantes del padrón.","No significa que votó el 70% de toda la población del país."],"easy":"Votaron siete de cada diez personas del padrón.","example":"Si hay 1.000 habilitados, 70% representa 700 votantes; no informa cuántos habitantes totales tiene el país."},"HIS-056":{"steps":["La ocupación de la Araucanía fue un proceso de expansión militar y administrativa del Estado chileno en el siglo XIX.","Implicó pérdida de control territorial y profundas transformaciones para comunidades mapuche.","No corresponde describirlo como un proceso sin conflicto ni consecuencias para la población originaria."],"easy":"El Estado incorporó territorios mediante un proceso que afectó gravemente a los mapuche.","example":"La instalación de instituciones estatales y la reducción de tierras mapuche transformaron sus formas de vida."},"HIS-057":{"steps":["El Plan Marshall fue anunciado en 1947 y aplicado desde 1948.","Estados Unidos aportó asistencia para reconstrucción y recuperación económica europea tras la Segunda Guerra Mundial.","No fue un plan de reconstrucción de Europa después de la Primera Guerra Mundial."],"easy":"Ayudó a recuperar economías europeas devastadas después de 1945.","example":"La ayuda apoyó la recuperación de producción e infraestructura en países de Europa occidental."},"HIS-058":{"steps":["La soberanía popular fundamenta la legitimidad del poder político en el pueblo.","En democracias representativas, se ejerce mediante instituciones y elecciones conforme al orden constitucional.","No significa que una autoridad pueda gobernar sin límites alegando apoyo popular."],"easy":"La autoridad política obtiene legitimidad de la ciudadanía.","example":"Elegir representantes en elecciones es una forma de ejercer soberanía popular dentro de reglas democráticas."},"HIS-059":{"steps":["El municipio solo puede financiar una de dos alternativas.","Al elegir la biblioteca, renuncia a mejorar la plaza.","El costo de oportunidad es el beneficio de la mejor alternativa descartada, no necesariamente su precio."],"easy":"Elegir una opción significa perder el beneficio de la mejor opción que dejaste pasar.","example":"Si la biblioteca se construye, el costo de oportunidad es el bienestar que habría generado mejorar la plaza."},"HIS-060":{"steps":["Una fotografía sin fecha ni lugar carece de contexto suficiente.","Antes de interpretarla, conviene identificar origen, autoría, fecha y autenticidad.","Una imagen real puede circular con un contexto falso y conducir a conclusiones erróneas."],"easy":"Primero verifica dónde y cuándo se tomó la foto.","example":"Una foto antigua de una protesta puede presentarse como si fuera reciente; revisar su procedencia evita ese error."},"HIS-061":{"steps":["En 1971 Chile aprobó una reforma constitucional para nacionalizar la gran minería del cobre.","El proceso transfirió al Estado la propiedad de empresas comprendidas en esa nacionalización.","No debe confundirse con la chilenización del cobre impulsada en la década anterior."],"easy":"La nacionalización de 1971 incorporó al Estado la gran minería del cobre.","example":"La reforma constitucional de 1971 es distinta de acuerdos previos de participación estatal en empresas cupríferas."},"HIS-062":{"steps":["La Gran Depresión se inició tras la crisis financiera de 1929 y se extendió internacionalmente.","Provocó caídas de producción y comercio y fuerte desempleo en numerosos países.","No fue solo una baja pasajera de la bolsa estadounidense."],"easy":"Fue una crisis económica profunda con consecuencias mundiales.","example":"La contracción del comercio internacional afectó economías exportadoras como la chilena."},"HIS-063":{"steps":["Las elecciones periódicas permiten elegir y renovar representantes.","También permiten evaluar gestiones y cambiar autoridades por vías institucionales.","Por sí solas no garantizan democracia plena sin derechos, competencia y garantías."],"easy":"La ciudadanía puede renovar o reemplazar a sus representantes mediante elecciones.","example":"En la siguiente elección, votantes pueden apoyar a una autoridad o elegir una alternativa según su desempeño."},"HIS-064":{"steps":["Un bien normal se define porque su demanda aumenta cuando crece el ingreso, manteniendo constantes otros factores.","El aumento del ingreso desplaza la curva de demanda hacia la derecha.","No debe confundirse con un movimiento por cambio en el precio del propio bien."],"easy":"Si ganas más, puedes querer comprar más de un bien normal.","example":"Si aumenta el ingreso familiar y se demandan más viajes de ocio, esos viajes se comportan como bien normal en ese caso."},"HIS-065":{"steps":["La tasa de desempleo divide personas desocupadas entre la fuerza de trabajo.","Dos países con igual cantidad de desempleados pueden tener tasas distintas si sus fuerzas laborales difieren.","Para comparar tasas hacen falta los tamaños de las fuerzas de trabajo."],"easy":"No basta saber cuántos desempleados hay: hay que saber cuántas personas integran la fuerza laboral.","example":"Con 100 desocupados y fuerza laboral de 1.000 la tasa es 10%; con fuerza laboral de 2.000 es 5%."}};
for(const q of window.CACHASTE_HISTORIA){if(HISTORIA_EDITORIAL_LOTE_4[q.id]){q.editorial=HISTORIA_EDITORIAL_LOTE_4[q.id];q.reviewStatus='revisado_conceptualmente';}}

const HISTORIA_EDITORIAL_LOTE_5={"HIS-021":{"steps":["En el norte chileno se explotaron minerales destinados al mercado nacional y exterior.","La minería atrajo trabajadores, transporte y servicios cerca de yacimientos.","Ese proceso impulsó ciudades mineras, no una urbanización desligada de la producción."],"easy":"La extracción y exportación de minerales hizo crecer asentamientos del norte.","example":"Los centros vinculados al cobre, la plata y el salitre necesitaron trabajadores y conexiones comerciales."},"HIS-022":{"steps":["La cuestión social se refiere a problemas de trabajo, salud y vivienda ligados a cambios económicos y urbanos.","Incluyó hacinamiento, precariedad y demandas de protección social.","No describe un conflicto único, sino un conjunto de condiciones y debates."],"easy":"Fue el conjunto de problemas que afectaban a trabajadores y familias urbanas.","example":"Los conventillos hacinados y las largas jornadas laborales son ejemplos de la cuestión social."},"HIS-023":{"steps":["En 1891 hubo una guerra civil entre fuerzas del presidente Balmaceda y sus opositores.","Tras la derrota presidencial se fortaleció el predominio parlamentario en la práctica.","Chile no se convirtió por ello en un régimen parlamentario idéntico al británico."],"easy":"Después de 1891 el Congreso adquirió mayor peso frente al Ejecutivo.","example":"La rotación ministerial y las prácticas congresistas caracterizaron el período parlamentario chileno."},"HIS-024":{"steps":["La CORFO fue creada en 1939 para impulsar la actividad productiva.","Promovió industrialización, infraestructura y desarrollo de sectores estratégicos.","Su objetivo no fue reemplazar toda actividad privada ni dedicarse solo a un rubro."],"easy":"La CORFO buscó desarrollar la industria y la producción chilena.","example":"La promoción de proyectos energéticos e industriales ayudó a ampliar la capacidad productiva nacional."},"HIS-025":{"steps":["La reforma agraria buscó modificar la concentración de propiedad de la tierra.","Incluyó expropiación y redistribución bajo marcos legales y transformaciones rurales.","No fue solo una mejora de maquinaria agrícola sin cambios de propiedad."],"easy":"La reforma agraria cambió la tenencia de la tierra y las relaciones del campo.","example":"La redistribución de grandes propiedades a nuevos beneficiarios modificó la estructura agraria."},"HIS-026":{"steps":["El plebiscito de 1988 preguntó por la continuidad de Augusto Pinochet en la presidencia.","Ganó la opción No.","El resultado abrió paso a elecciones presidenciales y al proceso de transición democrática."],"easy":"En 1988 ganó el No a la continuidad de Pinochet.","example":"La victoria del No condujo a elecciones en 1989 y al cambio de gobierno en 1990."},"HIS-027":{"steps":["Una fuente primaria se produce en el período o por actores vinculados al proceso investigado.","Permite estudiar testimonios y registros cercanos al hecho.","Ser primaria no la vuelve automáticamente imparcial ni completa."],"easy":"Una carta escrita durante un acontecimiento es fuente primaria sobre esa época.","example":"Para estudiar 1891, un periódico publicado ese año es fuente primaria que igualmente requiere análisis crítico."},"HIS-028":{"steps":["La historia se construye interpretando fuentes con preguntas y métodos.","Nuevos documentos pueden modificar explicaciones previas.","Cambiar una interpretación por evidencia no significa que todos los relatos valgan lo mismo."],"easy":"La interpretación histórica puede revisarse cuando aparecen nuevas pruebas.","example":"Un archivo recién descubierto puede precisar la fecha de un hecho o revelar actores antes omitidos."},"HIS-029":{"steps":["La Revolución Industrial concentró fábricas y empleo asalariado.","La búsqueda de trabajo atrajo población hacia ciudades industriales.","La urbanización se relacionó con oportunidades laborales y también con condiciones precarias."],"easy":"Las fábricas hicieron que muchas personas se trasladaran a ciudades.","example":"Una ciudad con talleres y fábricas crece al recibir trabajadores que buscan salario."},"HIS-030":{"steps":["La Guerra Fría enfrentó proyectos geopolíticos e ideológicos liderados por EE. UU. y la URSS.","Hubo competencia militar, tecnológica y diplomática y conflictos indirectos.","No consistió en una guerra directa generalizada entre ambos países."],"easy":"Fue una rivalidad global entre dos bloques de poder después de la Segunda Guerra Mundial.","example":"La carrera espacial y los conflictos por influencia internacional expresaron esa rivalidad."},"HIS-031":{"steps":["La Declaración francesa de 1789 formuló principios de libertad e igualdad jurídica.","Afirmó derechos y la igualdad ante la ley como ideales revolucionarios.","Su proclamación no significó aplicación universal e inmediata a todos los habitantes."],"easy":"Difundió la idea de que las personas poseen derechos y deben ser iguales ante la ley.","example":"La igualdad jurídica cuestionaba privilegios legales del Antiguo Régimen."},"HIS-032":{"steps":["El imperialismo europeo expandió dominios coloniales en África durante el siglo XIX.","Las potencias impusieron administraciones y reorganizaron territorios.","Las fronteras coloniales afectaron profundamente sociedades y economías locales."],"easy":"La expansión imperialista significó control colonial y cambios territoriales.","example":"La imposición de fronteras sin respetar necesariamente organizaciones locales dejó consecuencias duraderas."},"HIS-033":{"steps":["Después de 1945 crecieron movimientos anticoloniales y nacionalistas.","Esos movimientos exigieron independencia y autodeterminación en Asia y África.","La descolonización tuvo ritmos y vías distintas según territorio."],"easy":"Muchos pueblos colonizados lucharon por formar Estados independientes.","example":"India obtuvo su independencia en 1947; en África también avanzaron procesos de independencia en décadas posteriores."},"HIS-034":{"steps":["Una Constitución define competencias y límites de los órganos del Estado.","También establece derechos y mecanismos de control.","Una autoridad no puede actuar legítimamente fuera de sus atribuciones solo por tener apoyo político."],"easy":"La Constitución fija reglas que también obligan a quienes gobiernan.","example":"Una autoridad debe respetar derechos y atribuciones establecidos por el orden constitucional."},"HIS-035":{"steps":["La separación de poderes distribuye funciones estatales.","Establece controles y contrapesos para reducir concentración de autoridad.","No supone ausencia de coordinación entre instituciones."],"easy":"Dividir funciones ayuda a evitar que una sola institución controle todo.","example":"El Congreso legisla y fiscaliza, mientras tribunales resuelven controversias conforme a sus competencias."},"HIS-036":{"steps":["La participación democrática incluye votar, pero no termina allí.","Organizaciones, deliberación, consultas y fiscalización permiten intervenir en asuntos públicos.","No toda forma de participación equivale a decidir directamente una ley."],"easy":"También participas cuando opinas, te organizas y fiscalizas decisiones públicas.","example":"Vecinos que presentan observaciones en una consulta municipal participan sin esperar una elección."}};
for(const q of window.CACHASTE_HISTORIA){if(HISTORIA_EDITORIAL_LOTE_5[q.id]){q.editorial=HISTORIA_EDITORIAL_LOTE_5[q.id];q.reviewStatus='revisado_conceptualmente';}}
